agent_sql:
with b as (select business_id from yelp_business where attributes->>'BusinessAcceptsCreditCards'='True' and description ~ '\mRestaurants\M')
select 'Restaurants' as category, round(avg(r.rating)::numeric,2) as average_rating
from yelp_review r join b on r.business_ref = replace(b.business_id,'businessid_','businessref_')
